insert into public.apps (id, name, category, modality, status, badge, description, duplicate_of, kind, external_url, html_path, cover_path, tier, sort_order) values
  ('local-ct-mri-pns-studio', 'CT / MRI Paranasal Sinuses (PNS) Report Studio — Auto-Generator', 'Head, Neck & ENT', 'CT / MRI', 'Integrated', 'LUND-MACKAY • CLOSE • 28 PRESETS', 'Raw row-by-row PNS CT & MRI report studio covering all sinuses, OMC, nasal septum/turbinates, CLOSE surgical checklist, fungal/neoplastic/traumatic pathology, live Lund-Mackay calculator (0–24), 28 presets & Word export.', null, 'integrated', null, 'local-ct-mri-pns-studio.html', 'local-ct-mri-pns-studio.jpg', 'pro', 10),
  ('local-adrenal-mass-ct-mri-staging', 'Adrenal Mass CT / MRI — Structured Report & Staging Generator', 'Abdomen & GI', 'CT / MRI', 'Integrated', 'APW/RPW • CSI • TNM / ENSAT', 'Comprehensive adrenal CT & MRI structured report generator with live absolute/relative CT washout & MRI chemical shift calculators, conditional TNM/ENSAT staging, full benign-to-malignant pathology spectrum & Word (.docx) export.', null, 'integrated', null, 'local-adrenal-mass-ct-mri-staging.html', 'local-adrenal-mass-ct-mri-staging.jpg', 'pro', 20),
  ('local-ct-mr-orbit-pro', 'CT / MR Orbit — Structured Report Auto-Generator', 'Head, Neck & ENT', 'CT / MRI', 'Integrated', '24 ROWS • ORBITAL CONE • 28 PRESETS', '24-row structured CT & MRI orbit reporter covering globe, lens, retina/choroid, optic nerve & chiasm, extraocular muscles, intraconal/extraconal spaces, lacrimal & apex lesions, 28 clinical presets & Word export.', null, 'integrated', null, 'local-ct-mr-orbit-pro.html', 'local-ct-mr-orbit-pro.jpg', 'pro', 30),
  ('local-ct-facial-trauma-pro', 'CT Facial Trauma — Structured Report Auto-Generator', 'Head, Neck & ENT', 'CT', 'Integrated', 'LE FORT • AOCMF • ZINGG • NOE', 'Complete craniomaxillofacial CT trauma studio covering Le Fort I–III, AOCMF, Zingg ZMC, Markowitz-Manson NOE, Stranc-Robertson nasal, orbital blowout/trapdoor/apex, mandible/TMJ, skull base, post-ORIF & Word export.', null, 'integrated', null, 'local-ct-facial-trauma-pro.html', 'local-ct-facial-trauma-pro.jpg', 'pro', 40),
  ('local-ct-mr-brain-trauma-pro', 'CT / MR Brain Trauma — Structured Report Auto-Generator', 'Neuro & Brain', 'CT / MRI', 'Integrated', 'ROTTERDAM • MARSHALL • ABC÷2 • DAI', 'Structured CT & MRI TBI report generator covering EDH, SDH, tSAH, IVH, contusions, DAI/TAI, herniation & skull fractures with live Rotterdam, Marshall & ABC÷2 hematoma volume calculators, normal retention & Word export.', null, 'integrated', null, 'local-ct-mr-brain-trauma-pro.html', 'local-ct-mr-brain-trauma-pro.jpg', 'pro', 50),
  ('local-phakomatoses-neurocutaneous-pro', 'Phakomatoses Pro — Neurocutaneous Syndromes Multi-System CT & MRI', 'Neuro & Brain', 'CT / MRI', 'Integrated', 'NF1 • NF2 • TSC • SWS • VHL • COWDEN • 20 PRESETS', 'Multi-system neurocutaneous syndrome CT & MRI reporter covering NF1, NF2-Schwannomatosis, TSC (Tubers/SEGA/AML/LAM), Sturge-Weber, VHL (Hemangioblastoma/ELST/RCC/PanNET), Cowden/Lhermitte-Duclos, Gorlin-Goltz, AT, HHT & Word export.', null, 'integrated', null, 'local-phakomatoses-neurocutaneous-pro.html', 'local-phakomatoses-neurocutaneous-pro.jpg', 'pro', 60),
  ('local-dynamic-mri-abdomen-pro', 'Dynamic MRI Abdomen Pro — LI-RADS MRI, HBP, Bosniak v2019 & Adrenal CSI', 'Abdomen & GI', 'MRI', 'Integrated', 'LI-RADS MRI • EOVIST HBP • BOSNIAK • CSI • 20 PRESETS', 'Multiphasic contrast-enhanced abdominal MRI workstation spanning LI-RADS MRI & 20-min hepatobiliary phase (Eovist/Primovist), liver PDFF/R2*, biliary/pancreatic lesions, adrenal CSI, Bosniak v2019 renal masses & Word export.', null, 'integrated', null, 'local-dynamic-mri-abdomen-pro.html', 'local-dynamic-mri-abdomen-pro.jpg', 'pro', 70),
  ('local-ct-mri-gynecology-pro', 'CT / MRI Gynecology Pro — FIGO, #Enzian DIE, Mullerian & PAS Auto-Generator', 'Pelvis, GU & Oncology', 'CT / MRI', 'Integrated', 'FIGO 2023/2018 • #ENZIAN • ESHRE • PAS • 20 PRESETS', 'Comprehensive gynecologic CT & MRI structured reporter spanning Endometrial & Cervical FIGO staging, FIGO 0–8 fibroids & adenomyosis, #Enzian deep infiltrating endometriosis, ESHRE/ESGE Mullerian anomalies, Placenta Accreta Spectrum & Word export.', null, 'integrated', null, 'local-ct-mri-gynecology-pro.html', 'local-ct-mri-gynecology-pro.jpg', 'pro', 80),
  ('local-mr-defecography-pelvic-floor', 'MR Defecography Pro — Dynamic Pelvic Floor Structured Report Auto-Generator', 'Pelvis, GU & Oncology', 'MRI', 'Integrated', 'ESUR/SAR • HMO & PCL • OXFORD I–V • 18 PRESETS', 'Dynamic pelvic floor MR defecography reporter with live HMO (H/M-Line) & PCL auto-grading, Anterior/Middle/Posterior compartment prolapse, rectocele, Oxford I–V intussusception, enterocele/sigmoidocele, anismus & Word export.', null, 'integrated', null, 'local-mr-defecography-pelvic-floor.html', 'local-mr-defecography-pelvic-floor.jpg', 'pro', 90),
  ('local-cardiac-mri-cmr-pro', 'Cardiac MRI (CMR) Pro — SCMR Structured Report Auto-Generator', 'Chest, Cardiac & Vascular', 'MRI', 'Integrated', 'SCMR • LAKE LOUISE 2018 • AHA 17-SEG • 20 PRESETS', 'Comprehensive Cardiac MRI reporter covering ischemic viability/MVO, stress perfusion, non-ischemic cardiomyopathies (DCM, HCM, Amyloid, Sarcoid, ARVC, Fabry, Iron T2*, Takotsubo), Lake Louise myocarditis, AHA 17-segment bull''s-eye & Word export.', null, 'integrated', null, 'local-cardiac-mri-cmr-pro.html', 'local-cardiac-mri-cmr-pro.jpg', 'pro', 100),
  ('local-mri-perianal-fistula-parks', 'MRI Perianal Fistula — Parks & St. James''s Structured Report Auto-Generator', 'Pelvis, GU & Oncology', 'MRI', 'Integrated', 'PARKS • ST. JAMES''S 1–5 • ANAL CLOCK • 20 PRESETS', 'Interactive pelvic floor & perianal fistula MRI builder featuring Parks & St. James''s Grades 1–5, clickable Anal Clock-Face internal/external opening mapper, Crohn''s proctitis, horseshoe & supralevator abscesses, sphincter integrity & Word export.', null, 'integrated', null, 'local-mri-perianal-fistula-parks.html', 'local-mri-perianal-fistula-parks.jpg', 'pro', 110),
  ('local-msk-mri-pro-all-joints', 'MSK MRI Pro — Shoulder, Hip/SIJ, Ankle/Foot, Wrist/Hand, Elbow & Tumor Auto-Generator', 'Spine & MSK', 'MRI', 'Integrated', '6 MSK REGIONS • 30 PRESETS • BONE/ST-RADS', 'All-joint non-knee MSK MRI structured reporter covering Shoulder, Hip & SI Joints (ASAS/FAI/AVN), Ankle & Foot, Wrist & Hand (Palmer TFCC/SLL), Elbow, and Bone/Soft-Tissue Tumors (Bone-RADS/ST-RADS) with raw findings, headline-free impression & Word export.', null, 'integrated', null, 'local-msk-mri-pro-all-joints.html', 'local-msk-mri-pro-all-joints.jpg', 'pro', 120),
  ('local-ct-mri-petrous-cpa-ear', 'CT / MRI Petrous, CPA & Ear Pathology — Report Auto-Generator', 'Head, Neck & ENT', 'CT / MRI', 'Integrated', '6 ETIOLOGIC CATEGORIES • 37 PRESETS', 'Structured CT & MRI reporting across Outer, Middle & Inner Ear, Petrous Temporal Bone, and Cerebellopontine Angle (CPA) covering Congenital, Developmental, Traumatic, Inflammatory, Neoplastic & Acquired pathology with raw findings, impression & Word export.', null, 'integrated', null, 'local-ct-mri-petrous-cpa-ear.html', 'local-ct-mri-petrous-cpa-ear.jpg', 'pro', 130),
  ('local-spinemri-pro-lss-cs-ds-postop', 'SpineMRI Pro — LSS / CS / DS & Post-Op Contrast Auto-Generator', 'Spine & MSK', 'MRI', 'Integrated', 'LSS • CS • DS • POST-OP CONTRAST • 28 PRESETS', 'Interactive Lumbosacral (LSS), Cervical (CS), Dorsal/Thoracic (DS), Whole Spine & Postoperative Contrast MRI structured reporter spanning normal to marked spondylodegeneration, Modic/Pfirrmann/Schizas classifications & advanced complications with Word export.', null, 'integrated', null, 'local-spinemri-pro-lss-cs-ds-postop.html', 'local-spinemri-pro-lss-cs-ds-postop.jpg', 'pro', 140),
  ('local-ct-cap-trauma-aast', 'CT Chest, Abdomen & Pelvis Trauma — AAST Classification Report Generator', 'Trauma, ICU & Fluoroscopy', 'CT', 'Integrated', 'AAST OIS • SVS BTAI • YOUNG-BURGESS', 'Raw-findings trauma CT builder covering 25 thoracic, solid-organ, GI, vascular, GU, and pelvic items from Normal to Grade V/VI with 24 presets, live headline-free Impression synthesis, and Word export.', null, 'integrated', null, 'local-ct-cap-trauma-aast.html', 'local-ct-cap-trauma-aast.jpg', 'pro', 150),
