  ('local-mri-brain-stroke-perfusion', 'Brain MRI, MRA & MR Perfusion — Stroke Report Auto-Generator', 'Neuro & Brain', 'MRI', 'Integrated', 'DWI/PC-ASPECTS • DSC/ASL PERFUSION', 'Multiparametric stroke MRI, MRA & MR perfusion builder covering territorial, chronological, DWI/pc-ASPECTS, perfusion mismatch, complication, and STRIVE-2 findings with 24 presets and Word export.', null, 'integrated', null, 'local-mri-brain-stroke-perfusion.html', 'local-mri-brain-stroke-perfusion.jpg', 'pro', 170),
  ('local-mri-pelvis-ovarian-orads', 'Pelvic MRI Ovarian & Adnexal Lesion — O-RADS MRI 2022 Auto-Generator', 'Pelvis, GU & Oncology', 'MRI', 'Integrated', 'ACR O-RADS MRI 2022 • ADNEXAL', 'Structured pelvic MRI reporting engine spanning normal physiology, benign cysts, acute adnexal emergencies, benign/borderline neoplasms, and ovarian malignancies with real-time O-RADS MRI 2022 grading and Word export.', null, 'integrated', null, 'local-mri-pelvis-ovarian-orads.html', 'local-mri-pelvis-ovarian-orads.jpg', 'pro', 180),
